"""Certificate pinning utilities."""

import hashlib
import json
import os


def fingerprint(cert_der: bytes) -> str:
    """Compute the SHA-256 SPKI fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Manages a store of pinned certificate fingerprints per host."""

    def __init__(self, pins: dict = None):
        """Initialize with a dict mapping hosts to sets of fingerprint hex strings."""
        self._pins = pins or {}

    @classmethod
    def load(cls, path: str = None) -> "PinStore":
        """Load the pin store from a JSON file.

        Default location is the 'pins.json' file in the same directory as this package.
        If not found, falls back to the environment variable TESSARO_PIN_FILE.
        If neither exists, returns an empty pin store.
        """
        if path is None:
            path = os.environ.get("TESSARO_PIN_FILE")

        if path is not None:
            try:
                with open(path, "r") as f:
                    data = json.load(f)
                # Normalize: each value can be a list or set of fingerprint strings
                pins = {}
                for host, fingerprints in data.items():
                    if isinstance(fingerprints, (list, tuple)):
                        pins[host] = set(fingerprints)
                    else:
                        pins[host] = {fingerprints}
                return cls(pins)
            except FileNotFoundError:
                pass
            except json.JSONDecodeError:
                pass

        return cls()

    def matches(self, host: str, cert_fingerprint: str) -> bool:
        """Return True if the cert_fingerprint matches any pinned fingerprint for host."""
        host_pins = self._pins.get(host)
        if host_pins is None:
            return False
        return cert_fingerprint in host_pins

    def add(self, host: str, cert_fingerprint: str) -> None:
        """Add a fingerprint for a host."""
        if host not in self._pins:
            self._pins[host] = set()
        self._pins[host].add(cert_fingerprint)
